import java.util.*;

public class Main {
    List<List<Integer>> threeSum(int[] nums) {
        int n = nums.length;
        Set<List<Integer>> found = new HashSet<>();
        for (int i = 0; i < n; i++) {                             // try every first index
            for (int j = i + 1; j < n; j++) {                       // try every second index
                for (int k = j + 1; k < n; k++) {                     // try every third index
                    if (nums[i] + nums[j] + nums[k] == 0) {
                        List<Integer> triplet = new ArrayList<>(Arrays.asList(nums[i], nums[j], nums[k]));
                        Collections.sort(triplet);
                        found.add(triplet);                                 // a set naturally collapses duplicates
                    }
                }
            }
        }
        return new ArrayList<>(found);
    }

    public static void main(String[] args) {
        int[] nums = {-1, 0, 1, 2, -1, -4};
        Main solution = new Main();
        System.out.println(solution.threeSum(nums));
    }
}

