def three_sum(nums):
    nums.sort()                                             # bring equal values next to each other
    n = len(nums)
    result = []
    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue                                              # skip a duplicate fixed value
        left, right = i + 1, n - 1
        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total == 0:
                result.append([nums[i], nums[left], nums[right]])
                left += 1
                right -= 1
                while left < right and nums[left] == nums[left - 1]:
                    left += 1                                          # skip a duplicate left value
                while left < right and nums[right] == nums[right + 1]:
                    right -= 1                                          # skip a duplicate right value
            elif total < 0:
                left += 1                                                # sum too small, grow it
            else:
                right -= 1                                               # sum too large, shrink it
    return result


if __name__ == "__main__":
    nums = [-1, 0, 1, 2, -1, -4]
    print(three_sum(nums))

