import java.util.*;

public class Main {
    List<List<Integer>> threeSum(int[] nums) {
        Arrays.sort(nums);                                        // bring equal values next to each other
        int n = nums.length;
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < n - 2; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;             // skip a duplicate fixed value
            int left = i + 1, right = n - 1;
            while (left < right) {
                int total = nums[i] + nums[left] + nums[right];
                if (total == 0) {
                    result.add(Arrays.asList(nums[i], nums[left], nums[right]));
                    left++;
                    right--;
                    while (left < right && nums[left] == nums[left - 1]) left++;   // skip a duplicate left value
                    while (left < right && nums[right] == nums[right + 1]) right--; // skip a duplicate right value
                } else if (total < 0) {
                    left++;                                                   // sum too small, grow it
                } else {
                    right--;                                                   // sum too large, shrink it
                }
            }
        }
        return result;
    }

    public static void main(String[] args) {
        int[] nums = {-1, 0, 1, 2, -1, -4};
        Main solution = new Main();
        System.out.println(solution.threeSum(nums));
    }
